def wordSquares(words):
    n = len(words)
    result = []
    # Choose the top word
    for a in range(n):
        top = words[a]
        # Left word must share its first letter with top
        for b in range(n):
            if b == a:
                continue
            left = words[b]
            if left[0] != top[0]:
                continue
            # Right word must start with the last letter of top
            for c in range(n):
                if c == a or c == b:
                    continue
                right = words[c]
                if right[0] != top[3]:
                    continue
                # Bottom must close both lower corners
                for e in range(n):
                    if e == a or e == b or e == c:
                        continue
                    bottom = words[e]
                    if bottom[0] == left[3] and bottom[3] == right[3]:
                        result.append([top, left, right, bottom])
    # Lists compare element by element, matching the required (top, left, right, bottom) order
    result.sort()
    return result
